// web_form_car_repair_request.js
document.addEventListener('DOMContentLoaded', function() {
    const pickupCheckbox = document.querySelector('[name="vehicle_pick_up"]');
    const pickupAddressField = document.querySelector('[name="pick_up_address"]');

    if (!pickupCheckbox || !pickupAddressField) return;

    // Function to fill address using geolocation
    async function fillPickupAddress() {
        if (!navigator.geolocation) {
            alert('Geolocation not supported. Please enter address manually.');
            pickupAddressField.readOnly = false;
            return;
        }

        navigator.geolocation.getCurrentPosition(
            async (position) => {
                const lat = position.coords.latitude;
                const lng = position.coords.longitude;

                // Check if HTTPS or localhost
                if (location.protocol === 'https:' || location.hostname === 'localhost') {
                    try {
                        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
                        const data = await response.json();
                        pickupAddressField.value = data.display_name || `${lat}, ${lng}`;
                    } catch (err) {
                        pickupAddressField.value = `${lat}, ${lng}`;
                    }
                } else {
                    // HTTP LAN fallback: just fill lat/lng
                    pickupAddressField.value = `${lat}, ${lng} (enter full address manually)`;
                }
                pickupAddressField.readOnly = true;
            },
            (error) => {
                alert('Unable to fetch location! Please enter address manually.');
                pickupAddressField.readOnly = false;
            }
        );
    }

    // Checkbox change event
    pickupCheckbox.addEventListener('change', function() {
        if (this.checked) {
            fillPickupAddress();
        } else {
            pickupAddressField.value = '';
            pickupAddressField.readOnly = false;
        }
    });

    // On page load, set read-only if checkbox is already checked
    if (pickupCheckbox.checked) {
        pickupAddressField.readOnly = true;
    } else {
        pickupAddressField.readOnly = false;
    }
});
